Here is a sample Spark job to calculate the hit rate for onsite attributed data:

```java
import org.apache.spark.api.java.JavaPairRDD;
import org.apache.spark.api.java.JavaRDD;
import org.apache.spark.api.java.function.Function;
import org.apache.spark.api.java.function.PairFunction;
import scala.Tuple2;

import java.sql.Timestamp;
import java.util.HashMap;
import java.util.Map;

public class HitRateCalculator {

    public static void main(String[] args) {
        // Create Spark session
        JavaSparkContext sc = new JavaSparkContext(SparkConf.create());
        JavaSparkContext.hadoopConfiguration(sc).set("hadoop.home.dir", "/usr/local/hadoop");
        JavaSparkContext jsc = new JavaSparkContext(sc);
        JavaSparkSession session = JavaSparkSession.builder().appName("HitRateCalculator").config(sc.getConf()).getOrCreate();

        // Load onsite attributed data
        JavaRDD<String> onsiteAttributedData = jsc.textFile("path/to/onsite_attributed_data.csv");
        JavaRDD<String[]> onsiteAttributedDataRows = onsiteAttributedData.map(new Function<String, String[]>() {
            @Override
            public String[] call(String line) throws Exception {
                return line.split(",");
            }
        });
        JavaPairRDD<String, Timestamp> onsiteAttributedDataPairs = onsiteAttributedDataRows.mapToPair(new PairFunction<String[], String, Timestamp>() {
            @Override
            public Tuple2<String, Timestamp> call(String[] line) throws Exception {
                return new Tuple2<>(line[0], new Timestamp(Long.parseLong(line[1])));
            }
        });

        // Load top frequent queries
        JavaRDD<String> topFrequentQueries = jsc.textFile("path/to/top_frequent_queries.txt");
        Set<String> topFrequentQueriesSet = new HashSet<>(topFrequentQueries.collect());

        // Initialize cache
        Map<String, Timestamp> cache = new HashMap<>();

        // Process onsite attributed data
        onsiteAttributedDataPairs.foreach(new VoidFunction<Tuple2<String, Timestamp>>() {
            @Override
            public void call(Tuple2<String, Timestamp> pair) throws Exception {
                String query = pair._1();
                Timestamp timestamp = pair._2();

                // Check if query is in cache
                if (cache.containsKey(query)) {
                    // If query is in cache and timestamp is within 12 hours, consider it as a cache hit
                    if (timestamp.getTime() - cache.get(query).getTime() <= 12 * 60 * 60 * 1000) {
                        System.out.println("Cache Hit: " + query + ", " + timestamp);
                    } else {
                        // If query is in cache but timestamp is outside 12 hours, remove it from cache
                        cache.remove(query);
                    }
                } else {
                    // If query is not in cache, consider it as a cache miss and add it to cache
                    if (topFrequentQueriesSet.contains(query)) {
                        System.out.println("Cache Miss: " + query + ", " + timestamp);
                        cache.put(query, timestamp);
                    }
                }
            }
        });

        // Calculate hit rate
        double hitRate = (double) cache.size() / onsiteAttributedDataPairs.count();
        System.out.println("Hit Rate: " + hitRate);

        // Stop Spark session
        session.stop();
    }
}
```

