To compare two Excel files and show discrepancies in Node.js, you can use a combination of libraries such as `xlsx` for reading Excel files and `lodash` for comparing arrays. Here's a basic example:

1. First, install the necessary libraries:

```bash
npm install xlsx lodash
```

2. Create a new file, let's call it `compareExcel.js`:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareFiles(file1, file2, callback) {
  // Read the first workbook
  const workbook1 = XLSX.readFile(file1);
  const sheet_name_list1 = workbook1.SheetNames;
  const data1 = XLSX.utils.sheet_to_json(workbook1.Sheets[sheet_name_list1[0]]);

  // Read the second workbook
  const workbook2 = XLSX.readFile(file2);
  const sheet_name_list2 = workbook2.SheetNames;
  const data2 = XLSX.utils.sheet_to_json(workbook2.Sheets[sheet_name_list2[0]]);

  // Compare the arrays
  const differences = _.differenceWith(data1, data2, _.isEqual);

  // Call the callback with the differences
  callback(differences);
}

// Example usage:
compareFiles('file1.xlsx', 'file2.xlsx', (differences) => {
  console.log('Differences:', differences);
});
```

This script reads two Excel files and compares the first sheet of each. If there are any differences, it logs them to the console. You can adjust the sheet names and the comparison logic as needed.

