import java.util.Scanner;

class Dialogue {
    String text;
    String[] choices;
    Dialogue[] responses;

    Dialogue(String text, String[] choices, Dialogue[] responses) {
        this.text = text;
        this.choices = choices;
        this.responses = responses;
    }
}

class DialogueManager {
    Scanner scanner = new Scanner(System.in);

    void displayDialogue(Dialogue dialogue) {
        System.out.println(dialogue.text);
        for (int i = 0; i < dialogue.choices.length; i++) {
            System.out.println((i + 1) + ". " + dialogue.choices[i]);
        }
        System.out.print("Enter your choice (1-" + dialogue.choices.length + "): ");
        int choice = scanner.nextInt();
        if (choice < 1 || choice > dialogue.choices.length) {
            System.out.println("Invalid choice. Please try again.");
            displayDialogue(dialogue);
        } else {
            dialogue.responses[choice - 1].displayDialogue(this);
        }
    }

    Dialogue getPlayerChoice(Dialogue dialogue) {
        displayDialogue(dialogue);
        return dialogue.responses[scanner.nextInt() - 1];
    }
}
